#[cfg(test)]
mod tests {
    #![allow(unused_imports)]
    use super::*;
    use crate::field::FieldValue;
    use crate::packet::Packet;

    // protogen:tests begin
    /// IEEE 802.11-2020 §9.3.3.12: open system, sequence 1, status 0.
    fn vector() -> Vec<u8> {
        vec![0x00, 0x00, 0x01, 0x00, 0x00, 0x00]
    }

    #[test]
    fn dissects_the_rfc_vector() {
        let p = Packet::dissect(vector(), ProtoId::Dot11Auth);
        let l = p.find_layer(ProtoId::Dot11Auth).unwrap();
        assert_eq!(p.get(l, "algo").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "seqnum").unwrap(), FieldValue::Uint(1));
        assert_eq!(p.get(l, "status").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.raw_bytes(), &vector()[..]);
    }

    #[test]
    fn truncation_does_not_panic() {
        for n in 0..vector().len() {
            let p = Packet::dissect(vector()[..n].to_vec(), ProtoId::Dot11Auth);
            assert_eq!(p.raw_bytes(), &vector()[..n]);
        }
    }

    #[test]
    fn writes_survive_a_rebuild() {
        let mut p = Packet::dissect(vector(), ProtoId::Dot11Auth);
        let l = p.find_layer(ProtoId::Dot11Auth).unwrap();
        let n = p.raw_bytes().len();
        for f in crate::proto::active_fields(ProtoId::Dot11Auth, false, p.header(l))
            .filter(|f| f.kind == crate::field::FieldKind::Uint && f.bit_len <= 32)
            .map(|f| f.name)
            .collect::<Vec<_>>()
        {
            p.set_uint(l, f, 1);
        }
        assert_eq!(p.to_bytes().len(), n);
    }
    // protogen:tests end
}
